"""Build a local review page from the household catalogue and native captures."""
from pathlib import Path
import json

ROOT = Path(__file__).resolve().parents[1]
data = json.loads((ROOT / 'game/data/home_hierarchy.json').read_text('utf-8'))
rooms = [{key: room[key] for key in ['room_id', 'name', 'scene_level', 'theme', 'anchors', 'task']} for room in data['rooms']]
for room in rooms:
    for view in ['overview', 'play']:
        assert (ROOT / f"docs/verification/home-hierarchy-v1/native/{room['room_id']}-{view}.png").is_file()

template = r'''<!doctype html>
<html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>字母岛 · 小院与七个房间</title>
<style>
:root{color-scheme:light;--ink:#283f35;--muted:#6d786e;--paper:#f6f3e9;--green:#50745e;--line:#d9ded0}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.7 "Microsoft YaHei",system-ui,sans-serif}main{max-width:1480px;margin:auto;padding:46px 4vw 60px}a{color:#3d7659}header{max-width:980px}.eyebrow{font-size:12px;letter-spacing:.18em;color:var(--green);font-weight:700}h1{font-size:clamp(30px,4vw,54px);line-height:1.3;letter-spacing:-.035em;margin:16px 0}h2{font-size:26px;line-height:1.35;margin:0 0 12px}h3{margin:0 0 10px;font-size:18px}p{margin:10px 0 18px}.intro{max-width:820px;color:#536457;font-size:18px}.path{display:flex;flex-wrap:wrap;gap:9px;align-items:center;margin:26px 0 36px;font-size:14px}.path span{border:1px solid var(--line);padding:7px 14px;border-radius:7px;background:#fffdf5}.path .current{background:var(--green);color:#fff}.room-nav{display:flex;flex-wrap:wrap;gap:8px;border-bottom:1px solid var(--line);padding:0 0 18px}button{font:inherit;cursor:pointer;background:#fffdf6;color:var(--ink);border:1px solid #cbd4c5;padding:10px 17px;border-radius:8px}button:hover{border-color:var(--green)}button[aria-pressed=true]{background:var(--green);color:white;border-color:var(--green)}button:focus-visible,a:focus-visible{outline:3px solid #c79542;outline-offset:4px}.room-nav button:first-child{margin-right:15px}.stage{display:grid;grid-template-columns:minmax(0,1fr) 310px;gap:26px;padding:28px 0 35px;align-items:start}.visual{min-width:0}.visual img{width:100%;display:block;border-radius:10px;background:#d9e1d7;aspect-ratio:8/5;object-fit:contain}.view-bar{display:flex;gap:8px;margin-bottom:12px}.view-bar button{font-size:13px;padding:6px 12px}.caption{font-size:12px;color:var(--muted);margin:10px 0}.room-detail{padding-top:48px}.level{color:var(--green);font-size:12px;letter-spacing:.1em}.room-detail p{color:#5b6b60}.task{border-top:1px solid var(--line);padding-top:20px;margin-top:20px}.task ol{padding-left:20px;font-size:14px;color:#556659}.source-section{border-top:1px solid var(--line);padding:30px 0}.source-heading{display:flex;align-items:baseline;justify-content:space-between;gap:20px}.source-heading p{font-size:13px;color:var(--muted)}.sources{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px}.source{background:#fffcf3;border:1px solid #e2e3d7;border-radius:8px;padding:16px}.source b{font-size:15px}.source blockquote{font-size:15px;line-height:1.6;margin:12px 0 18px;color:#344f40}.source small{display:block;color:var(--muted);line-height:1.6}.lower{display:grid;grid-template-columns:1.1fr 1fr;gap:24px;border-top:1px solid var(--line);padding-top:32px;margin-top:10px}.lower img{width:100%;display:block;border-radius:8px}.lower p{font-size:14px;color:#5f6c61}.lower .view-bar{margin-top:14px}.evidence{margin-top:36px;border-top:1px solid var(--line);padding-top:28px}.stats{display:flex;gap:35px;flex-wrap:wrap;margin:18px 0 24px}.stats b{font-size:32px;line-height:1}.stats span{display:block;font-size:13px;margin-top:8px;color:var(--muted)}.evidence-links{display:flex;gap:20px;flex-wrap:wrap;font-size:14px}.note{font-size:13px;color:#738071;max-width:1000px}footer{font-size:12px;color:#7d8578;margin-top:28px}.lightbox{color:inherit;text-decoration:none}@media(max-width:1050px){.stage{grid-template-columns:1fr}.room-detail{padding-top:0;display:grid;grid-template-columns:1fr 1fr;gap:24px}.task{margin:0;border-top:0;border-left:1px solid var(--line);padding:0 0 0 24px}.sources{grid-template-columns:repeat(3,1fr)}}@media(max-width:680px){main{padding:28px 18px}.room-nav button{padding:8px 11px;font-size:14px}.room-nav button:first-child{margin-right:0}.room-detail,.lower{display:block}.task{margin:20px 0;border:0;border-top:1px solid var(--line);padding:20px 0 0}.sources{grid-template-columns:1fr}.source-heading{display:block}.lower>section+section{margin-top:30px}.stats{gap:20px}.view-bar button{padding:7px 10px}}
</style>
<main>
<header><div class="eyebrow">ALPHABET ISLAND / HOME</div><h1>从小院回家，<br>走进七个生活空间。</h1><p class="intro">家庭现在有了完整的二级住宅：小院、门廊、门厅和走廊连接七个独立房间。每个房间的用途，再由家具、生活活动与课本里的表达展开。</p></header>
<div class="path"><span>一级 · 字母岛</span> → <span class="current">二级 · 小院与住宅</span> → <span>三级 · 七个房间</span></div>
<nav id="rooms" class="room-nav" aria-label="查看不同家庭空间"></nav>
<section class="stage"><div class="visual"><div class="view-bar" aria-label="镜头类型"><button id="overview" aria-pressed="true">场景总览</button><button id="play" aria-pressed="false">实际游玩画面</button></div><a id="full" class="lightbox" target="_blank"><img id="scene" alt="家庭场景"></a><p id="caption" class="caption"></p></div><aside class="room-detail"><div><div id="level" class="level"></div><h2 id="title"></h2><p id="theme"></p></div><div class="task"><h3 id="task-title"></h3><ol id="steps"></ol><p id="result"></p></div></aside></section>
<section class="source-section"><div class="source-heading"><h2>五处物件，五段生活</h2><p>每句保留教材册次、单元与印刷页码；游戏里可听本地语音。</p></div><div id="sources" class="sources"></div></section>
<div class="lower"><section><h2>生活活动会留下可见变化</h2><p>以卧室整理床铺为例：通过三步操作改变床铺道具，完成后保存；中途放下会恢复原状态。</p><div class="view-bar" id="bed-controls"><button data-step="before" aria-pressed="true">动手之前</button><button data-step="middle" aria-pressed="false">整理过程中</button><button data-step="after" aria-pressed="false">整理完成</button></div><a id="bed-full" target="_blank"><img id="bed" alt="整理床铺的道具变化"></a><p class="caption">Godot 实际道具，使用检视镜头；这三步是按钮互动与人物手势，尚未制作逐物件抓取动画。</p></section>
<section><h2>先走到门前，再进入房间</h2><p>地图对应真实住宅布局。退出房间会回到对应的门前，再经院门返回字母岛。下面是 960 × 640 窗口中的游戏地图。</p><a href="verification/home-hierarchy-v1/native/home-estate-map-960.png" target="_blank"><img src="verification/home-hierarchy-v1/native/home-estate-map-960.png" alt="七个房间的实际游戏地图"></a><p class="caption">右侧列表可滚动；小院五点与“在家的一天”有单独入口。</p></section></div>
<section class="evidence"><h2>已经接入游戏，并完成家庭专项检查</h2><div class="stats"><div><b>7</b><span>独立三级房间</span></div><div><b>40</b><span>生活位置与教材引用</span></div><div><b>8</b><span>可保存的家务体验</span></div><div><b>56</b><span>实际角色行走路线</span></div><div><b>16</b><span>实际层级切换</span></div></div><p>从主岛家门进入小院；也可以从当前客厅出口回到住宅走廊。原有客厅保留旅行册、朋友角和装饰记录，休息与穿搭安排在卧室。</p><p class="note">房间划分与住宅建筑为原创设计。四上 Unit 9 直接提供客厅、卧室、厨房、浴室等房间知识；餐厅、书房、家务阳台结合其他册的吃饭、阅读、电脑与家务内容组织。40 句原文逐条核对本地八册教材清单，其中四上印刷页 51/52、五上印刷页 42 已人工查看。这里不代表八册完整课程，也不把生活体验计为英语掌握。</p><div class="evidence-links"><a href="planning/home-hierarchy/README.md">家庭设计与来源说明</a><a href="planning/home-hierarchy/source-audit.json">40 句来源审计</a><a href="verification/home-hierarchy-v1/hierarchy-report.json">实际导航与活动报告</a><a href="verification/home-hierarchy-v1/asset-report.json">原始素材保护与资产检查</a><a href="verification/home-hierarchy-v1/README.md">验证范围与复现方式</a></div></section>
<footer>所有场景图片均由本地 Godot 实际渲染。总览隐藏 HUD 并扩大镜头；“实际游玩画面”保留游戏默认镜头。点击图片可查看原图。</footer>
</main>
<script>
const rooms=__ROOM_DATA__;let selected=rooms[0],view='overview';const base='verification/home-hierarchy-v1/native/';const byId=id=>document.getElementById(id);
const shortNames=['小院与住宅','客厅','卧室','厨房','餐厅','浴室','书房','阳台'];
rooms.forEach((r,i)=>{const b=document.createElement('button');b.textContent=shortNames[i];b.dataset.room=r.room_id;b.onclick=()=>{selected=r;render()};byId('rooms').append(b)});
function render(){document.querySelectorAll('[data-room]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.room===selected.room_id));byId('level').textContent=selected.scene_level===2?'二级场景 / 院落、门厅与走廊':'三级场景 / 独立房间';byId('title').textContent=selected.name;byId('theme').textContent=selected.theme;byId('task-title').textContent=selected.task.title;byId('result').textContent=selected.task.result;byId('steps').replaceChildren(...selected.task.steps.map(s=>{const li=document.createElement('li');li.textContent=s;return li}));byId('sources').replaceChildren(...selected.anchors.map((a,i)=>{const el=document.createElement('article');el.className='source';const title=document.createElement('b');title.textContent=(i+1)+' · '+a.label;const quote=document.createElement('blockquote');quote.textContent=a.source.text;const ref=document.createElement('small');ref.textContent=a.source.book_title+' · '+a.source.unit_id.replace('unit-','Unit ')+' · 第 '+a.source.printed_page+' 页';el.append(title,quote,ref);return el}));const src=base+selected.room_id+'-'+view+'.png';byId('scene').src=src;byId('scene').alt=selected.name+' · '+(view==='play'?'实际游玩画面':'场景总览');byId('full').href=src;byId('caption').textContent=view==='play'?'实际游玩画面：保留默认镜头、角色和游戏界面。':'Godot 场景总览：仅扩大检视镜头并隐藏界面，使用实际游戏资产。';['overview','play'].forEach(v=>byId(v).setAttribute('aria-pressed',view===v))}
['overview','play'].forEach(v=>byId(v).onclick=()=>{view=v;render()});
function bed(step){const src=base+'bed-'+step+'.png';byId('bed').src=src;byId('bed-full').href=src;document.querySelectorAll('[data-step]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.step===step))}document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>bed(b.dataset.step));render();bed('before');
</script></html>'''
output = ROOT / 'docs/home-hierarchy-gallery.html'
output.write_text(template.replace('__ROOM_DATA__', json.dumps(rooms, ensure_ascii=False).replace('<', '\\u003c')), encoding='utf-8')
print(output)
